package io.knowledgebrain.media;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class DomainMediaApiTest {
 DomainMediaStore scopes;MediaStore media;ObjectStorage storage;DomainMediaController api;UUID space,context,owner,id;
 @BeforeEach void setup(){scopes=mock(DomainMediaStore.class);media=mock(MediaStore.class);storage=mock(ObjectStorage.class);api=new DomainMediaController(scopes,media,storage,"a".repeat(43),new SimpleMeterRegistry());var ids=new UuidV7(Clock.systemUTC());space=ids.next();context=ids.next();owner=ids.next();id=ids.next();}
 String body(){return "{\"spaceId\":\""+space+"\",\"contextId\":\""+context+"\",\"ownerId\":\""+owner+"\",\"mediaId\":\""+id+"\"}";}
 MockHttpServletRequest req(String body){var r=new MockHttpServletRequest("POST","/");r.setSecure(true);r.setContentType("application/json");r.addHeader("Authorization","Bearer "+"a".repeat(43));r.addHeader("traceparent","00-"+"a".repeat(32)+"-"+"b".repeat(16)+"-01");r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 void status(int n,org.junit.jupiter.api.function.Executable fn){assertEquals(n,assertThrows(ResponseStatusException.class,fn).getStatusCode().value());}
 @Test void onlySingletonDedicatedCredentialOverTlsIsAccepted(){var missing=req(body());missing.removeHeader("Authorization");var wrong=req(body());wrong.removeHeader("Authorization");wrong.addHeader("Authorization","Bearer "+"b".repeat(43));var duplicate=req(body());duplicate.addHeader("Authorization","Bearer "+"a".repeat(43));var tls=req(body());tls.setSecure(false);for(var r:List.of(missing,wrong,duplicate,tls))status(401,()->api.execute("get",r));verifyNoInteractions(scopes,media,storage);}
 @Test void malformedAndSpoofedRequestsNeverReachStorage(){for(String body:List.of("{}",body()+" {}",body().replace("}",",\"extra\":1}"),body().replace(id.toString(),id.toString().toUpperCase()),body().replace("mediaId","actorId")))status(400,()->api.execute("get",req(body)));var query=req(body());query.addParameter("url","evil");status(400,()->api.execute("get",query));var type=req(body());type.setContentType("text/plain");status(415,()->api.execute("get",type));status(413,()->api.execute("get",req("x".repeat(4097))));status(404,()->api.execute("delete",req(body())));verifyNoInteractions(scopes,media,storage);}
 @Test void immutableCompletionAndDownloadsUseTheScopedCanonicalFile()throws Exception{var info=new MediaStore.Info(id,space,"AVAILABLE",2,"a.pdf","application/pdf",1,"a".repeat(64),Instant.now(),Instant.now());var scope=new DomainMediaStore.Scope(space,context,owner);var reference=new DomainMediaStore.Reference(context,owner,info);when(scopes.get(scope,id)).thenReturn(reference);assertEquals(reference,api.execute("complete",req(body())).getBody());verifyNoInteractions(media,storage);var stored=new MediaStore.Stored(info,"sealed-original");when(media.available(space,id)).thenReturn(info);when(media.stored(space,id)).thenReturn(stored);when(storage.download(stored)).thenReturn(new ObjectStorage.Download("https://localhost:9443/brain-media/file",Instant.now().plusSeconds(300)));assertEquals("no-store",api.execute("download",req(body())).getHeaders().getCacheControl());verify(storage).download(stored);}
}
